<li id="main-traits_race_halfling-fake-fn-6-target"><p><Link to="/source/halflings_of_golarion">Halflings of Golarion</Link> <InnerLink aria-label="Back to reference 6" id="backlink-main-traits_race_halfling-fake-fn-6" data-hash-target to="main-traits_race_halfling-fake-fn-6">↩</InnerLink> <InnerLink aria-label="Back to reference 6" id="backlink-main-traits_race_halfling-fake-fn-6.2" data-hash-target to="main-traits_race_halfling-fake-fn-6.2">↩<sup>2</sup></InnerLink> <InnerLink aria-label="Back to reference 6" id="backlink-main-traits_race_halfling-fake-fn-6.3" data-hash-target to="main-traits_race_halfling-fake-fn-6.3">↩<sup>3</sup></InnerLink> <InnerLink aria-label="Back to reference 6" id="backlink-main-traits_race_halfling-fake-fn-6.4" data-hash-target to="main-traits_race_halfling-fake-fn-6.4">↩<sup>4</sup></InnerLink> <InnerLink aria-label="Back to reference 6" id="backlink-main-traits_race_halfling-fake-fn-6.5" data-hash-target to="main-traits_race_halfling-fake-fn-6.5">↩<sup>5</sup></InnerLink></p></li>
